checkpoint_inventory.criterion_pattern:
command -v python3 >/dev/null 2>&1 || exit 0
python3 - <<'PY'
try:
    import yaml
except ImportError:
    import sys; sys.exit(0)
import glob, sys
bad = []
for f in sorted(glob.glob('.github/workflows/*.yml')
                + glob.glob('.github/workflows/*.yaml')):
    try:
        with open(f) as fh:
            wf = yaml.safe_load(fh)
    except Exception:
        continue
    if not isinstance(wf, dict):
        continue
    for jname, job in (wf.get('jobs') or {}).items():
        if not isinstance(job, dict):
            continue
        # Skip reusable-workflow callers (no steps array).
        if 'uses' in job and 'steps' not in job:
            continue
        steps = job.get('steps')
        if not isinstance(steps, list) or not steps:
            continue
        first = steps[0] if isinstance(steps[0], dict) else {}
        uses = first.get('uses', '') or ''
        if not uses.startswith('step-security/harden-runner'):
            bad.append(f"{f}::{jname}")
if bad:
    sys.stderr.write("Jobs missing harden-runner as first step: "
                     + ", ".join(bad) + "\n")
    sys.exit(1)
sys.exit(0)
PY

[ -d Classes ] || exit 0
[ -f Configuration/Services.yaml ] || exit 0
find Classes -type f -name '*.php' -not -path '*/vendor/*' -not -path '*/node_modules/*' -not -path '*/.Build/*' 2>/dev/null | php -r '
$files = array_filter(array_map("trim", explode("\n", stream_get_contents(STDIN))), "is_file");
$yaml = file_get_contents("Configuration/Services.yaml");
// Service ids directly under `services:` (quoted or not). A key under
// `_instanceof:`, `bind:`, `arguments:` or any other nested map is not
// an alias and is not collected.
$keys = []; $in = false; $ind = -1;
foreach (preg_split("/\R/", $yaml) as $l) {
    if (preg_match("~^[^\s#]~", $l)) { $in = (bool) preg_match("~^services:\s*(#.*)?$~", $l); $ind = -1; continue; }
    if (!$in || preg_match("~^\s*(#|$)~", $l)) continue;
    $i = strlen($l) - strlen(ltrim($l, " \t"));
    if ($ind < 0) $ind = $i;
    if ($i !== $ind) continue;
    if (!preg_match("~^\s*(\x27[^\x27]*\x27|\"(?:[^\"\\\\]|\\\\.)*\"|[^\s:#\x27\"][^:]*?)\s*:(\s|$)~", $l, $m)) continue;
    $k = $m[1];
    if ($k[0] === "\x27") $k = substr($k, 1, -1);
    elseif ($k[0] === "\"") $k = stripcslashes(substr($k, 1, -1));
    $keys[ltrim($k, "\\")] = true;
}
$own = [];          // FQCN => true for interfaces declared under Classes/
$injected = [];     // FQCN => "file" of the first constructor naming it
$implementors = []; // FQCN of interface => list of [class, hasAsAlias, asAliasTarget]
foreach ($files as $f) {
    $t = array_values(array_filter(token_get_all(file_get_contents($f)), fn($x) => !(is_array($x) && in_array($x[0], [T_WHITESPACE, T_COMMENT, T_DOC_COMMENT], true))));
    $ns = ""; $uses = []; $n = count($t); $asAlias = [];
    $resolve = function (string $name) use (&$ns, &$uses): string {
        if ($name[0] === "\\") return ltrim($name, "\\");
        $first = explode("\\", $name)[0];
        if (isset($uses[$first])) return $uses[$first] . substr($name, strlen($first));
        return ltrim($ns . "\\" . $name, "\\");
    };
    $nameAt = function (int $i) use ($t): ?string {
        return is_array($t[$i] ?? null) && in_array($t[$i][0], [T_STRING, T_NAME_QUALIFIED, T_NAME_FULLY_QUALIFIED], true) ? $t[$i][1] : null;
    };
    $depth = 0;
    for ($i = 0; $i < $n; $i++) {
        $tok = $t[$i]; $id = is_array($tok) ? $tok[0] : $tok;
        if ($id === "{" || $id === T_CURLY_OPEN || $id === T_DOLLAR_OPEN_CURLY_BRACES) { $depth++; continue; }
        if ($id === "}") { $depth--; continue; }
        if ($id === T_NAMESPACE && ($nm = $nameAt($i + 1)) !== null) { $ns = $nm; continue; }
        // Every clause of `use A\B, C\D as E;` and every member of the
        // group form `use A\{B, C\D as E};`; `function` and `const`
        // members are skipped.
        if ($id === T_USE && $depth === 0 && $nameAt($i + 1) !== null) {
            $prefix = ""; $grp = false;
            for ($j = $i + 1; $j < $n && $t[$j] !== ";"; $j++) {
                if ($t[$j] === "{") { $grp = true; continue; }
                if ($t[$j] === "}") { $grp = false; $prefix = ""; continue; }
                if (is_array($t[$j]) && in_array($t[$j][0], [T_FUNCTION, T_CONST], true)) { $j++; continue; }
                if (($nm = $nameAt($j)) === null) continue;
                if (!$grp && is_array($t[$j + 1] ?? null) && $t[$j + 1][0] === T_NS_SEPARATOR && ($t[$j + 2] ?? null) === "{") { $prefix = ltrim($nm, "\\") . "\\"; $j++; continue; }
                $alias = substr(strrchr("\\" . $nm, "\\"), 1);
                if (is_array($t[$j + 1] ?? null) && $t[$j + 1][0] === T_AS) { $alias = $t[$j + 2][1]; $j += 2; }
                $uses[$alias] = ltrim($prefix . $nm, "\\");
            }
            $i = $j;
            continue;
        }
        if ($id === T_ATTRIBUTE) {
            $nm = $nameAt($i + 1);
            if ($nm !== null && str_ends_with($nm, "AsAlias")) {
                $target = "";
                $o = $i + 3; // #[AsAlias(Foo::class)] or the named form #[AsAlias(id: Foo::class)]
                if (is_array($t[$o] ?? null) && $t[$o][0] === T_STRING && $t[$o][1] === "id" && ($t[$o + 1] ?? null) === ":") $o += 2;
                if (($t[$i + 2] ?? null) === "(" && ($a = $nameAt($o)) !== null && is_array($t[$o + 1] ?? null) && $t[$o + 1][0] === T_DOUBLE_COLON) $target = $resolve($a);
                $asAlias[] = $target; // "" is a bare #[AsAlias]; the attribute is repeatable
            }
            continue;
        }
        if ($id === T_INTERFACE && ($nm = $nameAt($i + 1)) !== null) { $own[$resolve($nm)] = true; continue; }
        if ($id === T_CLASS && ($nm = $nameAt($i + 1)) !== null && !(is_array($t[$i - 1] ?? null) && $t[$i - 1][0] === T_DOUBLE_COLON)) {
            $cls = $resolve($nm); $ifs = [];
            for ($j = $i + 2; $j < $n && $t[$j] !== "{"; $j++) {
                if (is_array($t[$j]) && $t[$j][0] === T_IMPLEMENTS) {
                    for ($k = $j + 1; $k < $n && $t[$k] !== "{"; $k++) if (($x = $nameAt($k)) !== null) $ifs[] = $resolve($x);
                    break;
                }
            }
            foreach ($ifs as $if) $implementors[$if][] = [$cls, in_array($if, $asAlias, true) || (in_array("", $asAlias, true) && count($ifs) === 1)];
            $asAlias = [];
            continue;
        }
        if ($id === T_FUNCTION && ($t[$i + 1][1] ?? "") === "__construct" && ($t[$i + 2] ?? null) === "(") {
            $level = 0;
            for ($j = $i + 2; $j < $n; $j++) {
                if ($t[$j] === "(") $level++;
                elseif ($t[$j] === ")") { if (--$level === 0) break; }
                elseif ($level === 1 && ($x = $nameAt($j)) !== null && !(is_array($t[$j + 1]) && $t[$j + 1][0] === T_DOUBLE_COLON)) {
                    $fq = $resolve($x);
                    $injected[$fq] ??= $f;
                }
            }
        }
    }
}
$missing = 0;
foreach ($injected as $fq => $f) {
    if (!isset($own[$fq])) continue;
    if (isset($keys[$fq])) continue;
    $viaAttr = array_filter($implementors[$fq] ?? [], fn($c) => $c[1]);
    if ($viaAttr !== []) continue;
    echo "WARN: $fq is injected by a constructor ($f) but has no alias (Services.yaml key or #[AsAlias])\n";
    $missing = 1;
}
exit($missing);
'
